of scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }];
